#include "model.hpp"
#include <iomanip>
#include <sstream>
namespace pe {
std::string activity_name(ActivityKind k){static const char*names[]={"Idle","Work","Travel","Meal preparation","Drink","Rest","Conversation","Study","Collect water","Self care"};return names[int(k)];}
namespace {
std::string q(const std::string&s){std::string out="\"";const char*hex="0123456789abcdef";for(unsigned char c:s){if(c=='"'||c=='\\'){out+='\\';out+=char(c);}else if(c<32){out+="\\u00";out+=hex[c>>4];out+=hex[c&15];}else out+=char(c);}return out+'"';}
void inv(std::ostream&o,const Inventory&i){o<<'[';for(int j=0;j<goods;++j){if(j)o<<',';o<<i.units[j];}o<<']';}
}
std::string project(const State&s,Id viewer,bool debug){const auto&v=person(s,viewer);std::ostringstream o;o<<std::setprecision(10);o<<"{\"rules\":\"trial-a2\",\"seed\":"<<s.seed<<",\"tick\":"<<s.tick<<",\"revision\":"<<s.revision<<",\"viewer\":"<<viewer<<",\"debug\":"<<(debug?"true":"false")<<",\"treasury\":"<<s.government.account.money<<",\"office_holder\":"<<s.government.office.holder<<",\"locations\":[";
 bool first=true;for(auto&[id,l]:s.territory.locations){if(!first)o<<',';first=false;o<<"{\"id\":"<<id<<",\"name\":"<<q(l.name)<<",\"owner\":"<<l.owner<<",\"x\":"<<l.x<<",\"y\":"<<l.y;if(debug||v.location==id){o<<",\"stock\":";inv(o,l.stock);o<<",\"job\":"<<(l.job?"true":"false")<<",\"tool\":"<<(l.tool?"true":"false")<<",\"tool_uses\":"<<l.tool_uses<<",\"wage\":"<<l.wage;}o<<'}';}
 o<<"],\"people\":[";first=true;for(auto&[id,p]:s.people){if(!debug&&id!=viewer&&p.location!=v.location)continue;if(!first)o<<',';first=false;bool own=debug||id==viewer;o<<"{\"id\":"<<id<<",\"name\":"<<q(p.name)<<",\"location\":"<<p.location;if(own){o<<",\"money\":"<<p.account.money<<",\"inventory\":";inv(o,p.account.inventory);o<<",\"hunger\":"<<p.body.hunger<<",\"thirst\":"<<p.body.thirst<<",\"fatigue\":"<<p.body.fatigue<<",\"health\":"<<p.body.health<<",\"joy\":"<<p.body.joy<<",\"skills\":["<<p.experience.farming<<','<<p.experience.crafting<<','<<p.experience.communication<<"],\"tendencies\":["<<p.tendencies.security<<','<<p.tendencies.pleasure<<','<<p.tendencies.mobility<<"],\"goal\":"<<q(p.goal)<<",\"activity\":"<<q(activity_name(p.activity.kind))<<",\"target\":"<<p.activity.target<<",\"progress\":"<<p.activity.progress<<",\"required\":"<<p.activity.required<<",\"escrow\":"<<p.activity.escrow<<",\"reserved\":";inv(o,p.activity.reserved);o<<",\"relations\":{";bool rf=true;for(auto&[other,val]:p.relations){if(!rf)o<<',';rf=false;o<<q(std::to_string(other))<<':'<<val;}o<<'}';}o<<'}';}
 o<<"],\"facts\":[";first=true;for(auto&f:v.knowledge){if(!first)o<<',';first=false;o<<"{\"event\":"<<f.event<<",\"source\":"<<f.source<<",\"happened\":"<<f.happened<<",\"received\":"<<f.received<<",\"text\":"<<q(f.text)<<'}';}
 o<<"],\"events\":[";first=true;for(auto&e:s.events){if(!debug&&std::find(e.witnesses.begin(),e.witnesses.end(),viewer)==e.witnesses.end())continue;if(!first)o<<',';first=false;o<<"{\"id\":"<<e.id<<",\"tick\":"<<e.tick<<",\"text\":"<<q(e.text)<<'}';}
 o<<"],\"requests\":[";first=true;for(auto&r:s.requests){if(!debug&&r.from!=viewer&&r.to!=viewer)continue;if(!first)o<<',';first=false;o<<"{\"id\":"<<r.id<<",\"from\":"<<r.from<<",\"to\":"<<r.to<<",\"status\":"<<r.status<<'}';}
 o<<"],\"proposals\":[";first=true;for(auto& p:s.proposals){if(!debug&&p.from!=viewer&&p.to!=viewer&&!(p.to==0&&p.site==v.location&&p.status==ContractStatus::Pending))continue;if(!first)o<<',';first=false;o<<"{\"id\":"<<p.id<<",\"kind\":"<<int(p.kind)<<",\"from\":"<<p.from<<",\"to\":"<<p.to<<",\"author\":"<<p.author<<",\"awaiting\":"<<p.awaiting<<",\"site\":"<<p.site<<",\"good\":"<<int(p.good)<<",\"amount\":"<<p.amount<<",\"price\":"<<p.price<<",\"duration\":"<<p.duration<<",\"deadline\":"<<p.deadline<<",\"status\":"<<int(p.status)<<",\"escrow\":"<<p.escrow<<'}';}
 o<<"],\"debts\":[";first=true;for(auto& d:s.debts){if(!debug&&d.lender!=viewer&&d.borrower!=viewer)continue;if(!first)o<<',';first=false;o<<"{\"id\":"<<d.id<<",\"lender\":"<<d.lender<<",\"borrower\":"<<d.borrower<<",\"outstanding\":"<<d.outstanding<<",\"due\":"<<d.due<<",\"status\":"<<d.status<<'}';}
 o<<"],\"leases\":[";first=true;for(auto& l:s.leases){if(!debug&&l.landlord!=viewer&&l.tenant!=viewer)continue;if(!first)o<<',';first=false;o<<"{\"id\":"<<l.id<<",\"landlord\":"<<l.landlord<<",\"tenant\":"<<l.tenant<<",\"site\":"<<l.site<<",\"end\":"<<l.end<<",\"rent\":"<<l.rent<<",\"status\":"<<l.status<<'}';}
 o<<"],\"actions\":[";first=true;for(auto&a:World::definitions()){if(!first)o<<',';first=false;o<<"{\"verb\":"<<q(a.verb)<<",\"parameters\":"<<q(a.parameters)<<",\"description\":"<<q(a.description)<<",\"named\":[";bool nf=true;for(auto& name:action_registry().at(a.verb).named_parameters){if(!nf)o<<',';nf=false;o<<q(name);}o<<"]}";}o<<"]}";return o.str();}
}
